from rich.console import Console
import io

def test_disabled_progress_outputs_blank_line():
    output = io.StringIO()
    console = Console(file=output, force_terminal=False)

    # Use Progress with disabled=True
    with Progress(console=console, disable=True) as progress:
        pass

    result = output.getvalue()
    print(f"Output: {repr(result)}")
    if result == "\n":
        print("Bug reproduced: Blank line output when disabled")
    elif result == "":
        print("No blank line output")
    else:
        print(f"Other output: {repr(result)}")

if __name__ == "__main__":
    test_disabled_progress_outputs_blank_line()
